package org.apache.commons.lang3;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

public class DevPilotBitFieldTest extends AbstractLangTest {

    @Test
    public void testClearInt() {
        BitField bitField = new BitField(0x80000000);
        assertEquals(-1, bitField.clear(0));
    }

    @Test
    public void testClearLong() {
        BitField bitField = new BitField(0x80000000L);
        assertEquals(-1L, bitField.clear(0L));
    }
}
